(() => {
  const select = document.getElementById('location');
  if (!select || document.getElementById('countrySearch')) return;

  // ISO 3166-1 alpha-2 country list. Names are generated by the browser so the
  // selector stays maintainable and supports all countries without a huge HTML list.
  const codes = `AF AL DZ AS AD AO AI AQ AG AR AM AW AU AT AZ BS BH BD BB BY BE BZ BJ BM BT BO BQ BA BW BV BR IO BN BG BF BI CV KH CM CA KY CF TD CL CN CX CC CO KM CG CD CK CR CI HR CU CW CY CZ DK DJ DM DO EC EG SV GQ ER EE SZ ET FK FO FJ FI FR GF PF TF GA GM GE DE GH GI GR GL GD GP GU GT GG GN GW GY HT HM VA HN HK HU IS IN ID IR IQ IE IM IL IT JM JP JE JO KZ KE KI KP KR KW KG LA LV LB LS LR LY LI LT LU MO MG MW MY MV ML MT MH MQ MR MU YT MX FM MD MC MN ME MS MA MZ MM NA NR NP NL NC NZ NI NE NG NU NF MK MP NO OM PK PW PS PA PG PY PE PH PN PL PT PR QA RE RO RU RW BL SH KN LC MF PM VC WS SM ST SA SN RS SC SL SG SX SK SI SB SO ZA GS SS ES LK SD SR SJ SE CH SY TW TJ TZ TH TL TG TK TO TT TN TR TM TC TV UG UA AE GB US UM UY UZ VU VE VN VG VI WF EH YE ZM ZW`.split(' ');

  const displayNames = typeof Intl !== 'undefined' && Intl.DisplayNames
    ? new Intl.DisplayNames(['en'], { type: 'region' }) : null;
  const countries = codes.map(code => ({
    code,
    name: displayNames?.of(code) || code
  })).filter(x => x.name && x.name !== x.code).sort((a,b) => a.name.localeCompare(b.name));

  const flag = code => code.replace(/[A-Z]/g, c => String.fromCodePoint(127397 + c.charCodeAt(0)));
  const previous = select.value;
  select.innerHTML = '<option value="">🌎 Worldwide</option>';
  countries.forEach(({code,name}) => {
    const o = document.createElement('option');
    o.value = name;
    o.textContent = `${flag(code)}  ${name}`;
    o.dataset.code = code;
    select.appendChild(o);
  });
  const other = document.createElement('option');
  other.value = '';
  other.textContent = '🌍 Worldwide / no specific country';
  select.appendChild(other);
  if ([...select.options].some(o => o.value === previous)) select.value = previous;

  const label = select.previousElementSibling;
  const wrap = document.createElement('div');
  wrap.className = 'country-picker-wrap';
  const search = document.createElement('input');
  search.id = 'countrySearch';
  search.type = 'search';
  search.placeholder = '🔎 Search your country...';
  search.autocomplete = 'off';
  search.setAttribute('aria-label', 'Search countries');
  wrap.appendChild(search);
  select.parentNode.insertBefore(wrap, select);

  // Native select is kept for compatibility; typing filters it instantly.
  search.addEventListener('input', () => {
    const q = search.value.trim().toLowerCase();
    [...select.options].forEach(o => {
      if (!o.value) { o.hidden = false; return; }
      const code = o.dataset.code || '';
      o.hidden = !!q && !o.textContent.toLowerCase().includes(q) && !code.toLowerCase().includes(q);
    });
    const first = [...select.options].find(o => !o.hidden && o.value);
    if (q && first) select.value = first.value;
  });
  search.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); select.focus(); }
  });

  // Make remote search explicit and prominent.
  const remote = document.getElementById('remote');
  if (remote) {
    const check = remote.closest('.check');
    if (check) {
      check.innerHTML = '<input id="remote" type="checkbox" checked> <span>🏠 <b>Find remote jobs too</b><small>Include work-from-home and location-independent roles</small></span>';
    }
  }
})();
